save_baseline(root, &b2, "A6")?;
let unknown = catalogue
    .iter()
    .filter(|e| e["finding_state"] == "UNKNOWN")
    .count();
for n in batches {
    let mut entry = json!({"batch": n, "at": now_iso()});
    if n == 0 {
        // AR88-C10B, mirrored defensively (P2-AR-0089): captured before anything below can create
        // `framework.lock`, so a re-run of batch 0 against an ALREADY-onboarded project (this brownfield
        // route has no `--force` flag of its own, but nothing upstream of this function currently refuses a
        // repeat run) cannot rewrite the authoritative floor outside the governed route either -- same
        // reasoning as `init::init`, see its own comment.
        let already_installed = root.join("governance/framework.lock").exists();
        let src = resolve_kernel_source(source.map(Path::new))?;
        let gov = root.join("governance");
        std::fs::create_dir_all(&gov)?;
        // Privileged lifecycle ingress `adopt`: the one verification policy. Brownfield adoption installs a
        // kernel exactly like `init` does, so it is admitted through the same verifier and bound by the same
        // floors (ARCH-0003 §3.6; OWNER-DECISION-0006 §9).
        let mut adopt_auth: Option<crate::srr::AuthenticatedRelease> = None;
        let manifest = if root.join("governance/framework.lock").exists() {
            crate::kernel::read_manifest(&gov.join("kernel"))?
        } else {
            let a = crate::srr::admit(
                crate::srr::AdmissionRequest::new(crate::srr::Ingress::Adopt, &src)
                    .with_reason(Some("gov adopt migrate (batch 0)".into())),
            )?;
            let m = install_kernel(&a, &gov)?;
            adopt_auth = Some(a);
            m
        };
        if !root.join("governance/framework.lock").exists() {
            let consumer_commit = Project::open(root).git_commit();
            let release_commit = crate::kernel::release_commit_for_source(&src);
            write_lock(
                &gov.join("framework.lock"),
                &manifest,
                &crate::kernel::source_label(&src),
                Some(&release_commit),
                Some(&consumer_commit),
            )?;
        }
        let (mut contract, adoption_floor) =
            brownfield_contract(root, &gov.join("kernel"), &classified, &catalogue)?;
        // **P2-AR-0096 (P2-HO-0060 §2/§3): derivation computed HERE, before `write_overlay`.** The actual
        // floor WRITE stays deferred to its original point below (after the kernel install is committed and
        // verified, SRR-R0-L5) -- but the CONTRACT and the FLOOR must agree on which patterns they cover: a
        // restored pattern the union adds to the floor but the overlay never declares reads, at
        // `PolicySet::load`, as "a kernel-mandated pattern is missing from the overlay" -- a spurious D027
        // refusal the union must not itself introduce. So the union is computed early enough to splice the
        // SAME restored rules into `contract["paths"]` before it is ever written. `already_installed` alone
        // no longer decides whether the floor is (re)written: a RELOCATED checkout also carries
        // `framework.lock` but has no local `FloorIdentity` anchor for its NEW canonical path, and `gov
        // floor-reanchor` -- the only way back -- is deleted whole. `reonboarding` names exactly that case
        // (mirroring `init::init`'s own extended condition -- see its own comment for why this does not
        // reopen AR88-C10B: an ordinary in-place reshape never changes this checkout's canonical path, so
        // `has_local_adoption_anchor` still finds its existing entry and this branch stays false for it).
        let reonboarding = already_installed && !crate::paths::has_local_adoption_anchor(root);
        let mut adoption_floor_reonboarding = Value::Null;
        let floor_to_write = if reonboarding {
            let unioned = crate::paths::union_last_known_rules_across_store(&adoption_floor);
            let fresh_patterns: std::collections::BTreeSet<&str> = adoption_floor
                .iter()
                .filter_map(|r| r.get("pattern").and_then(|v| v.as_str()))
                .collect();
            let restored_rules: Vec<Value> = unioned
                .iter()
                .filter(|r| {
                    r.get("pattern")
                        .and_then(|v| v.as_str())
                        .map(|p| !fresh_patterns.contains(p))
                        .unwrap_or(false)
                })
                .cloned()
                .collect();
            let restored: Vec<String> = restored_rules
                .iter()
                .filter_map(|r| r.get("pattern").and_then(|v| v.as_str()).map(str::to_string))
                .collect();
            if !restored_rules.is_empty() {
                if let Some(arr) = contract["paths"].as_array_mut() {
                    let mut merged = restored_rules.clone();
                    merged.extend(arr.clone());
                    *arr = merged;
                }
            }
            adoption_floor_reonboarding = json!({
                "event": "PROJECT_ADOPTION_FLOOR_REONBOARDED",
                "reason": "this checkout already has a kernel installation (framework.lock) but no \
                           authenticated floor anchor for its current path -- a relocation, or a repeat \
                           onboarding with no local ledger; the floor was re-derived from this \
                           repository's own current native layout, strengthened by the machine's own \
                           protected record of every rule any checkout here has last seen authenticated, \
                           and re-authenticated under a FRESH identity (P2-HO-0060). The previous path's \
                           machine-store entry, if any, is left untouched and inert.",
                "restored_from_protected_machine_state": restored,
            });
            unioned
        } else {
            adoption_floor.clone()
        };
        let opts = crate::init::InitOptions {
            source: None,
            project_name: project_name.into(),
            alias: alias.into(),
            mode: "adopt".into(),
            force: false,
            intent: None,
            skip_index: true,
            channel: None,
            break_glass: false,
        };
        let written =
            crate::init::write_overlay(root, &gov.join("kernel"), &opts, Some(contract))?;
        let sensitivity_written =
            write_adoption_sensitivity(root, &classified, &catalogue)?;
        crate::init::ensure_roots(root)?;
        let mut p = Project::open(root);
        p.invalidate();
        crate::tools::generate_registry(&p)?;
        crate::adapters::generate(&p)?;
        let gates_created = ensure_destructive_gates(root, &mut catalogue)?;
        // Transaction step (9): floors advance only after the install is committed and verified (SRR-R0-L5).
        let protected = match adopt_auth.as_ref() {
            Some(a) => crate::srr::record_installed(a)?,
            None => Value::Null,
        };
        // P2-HO-0056 §3 / OD-P2-08 §2, precondition P1: WIRED (P2-AR-0081). P2-AR-0080 shipped this call
        // disabled after bisecting `brownfield::brownfield_adoption_end_to_end` /
        // `migration::adoption_independence_is_bound_to_declared_roles_and_approved_artefacts` failing at
        // `adopt migrate --batch 7` with `src/app/old_export.py` (an already-gate-approved DELETE_FROM_
        // ACTIVE_TREE artefact under a native, now-floored `src/**`) found still present, batch rolled back.
        // That round's own comment named the symptom it read off the black-box harness -- "requires an
        // answered human gate" -- and guessed a T2/`machine_view`/portable-key-scope interaction. Instrumented
        // reproduction (P2-AR-0081) found neither is true: zero T2 FOREIGN/BROKEN/UNSEALED events occur
        // anywhere in this scenario, `entry_gate_answer` correctly recognises the answered gate (subject hash
        // matches, `a.option == "A"`), and `answered_destructive` correctly includes this artefact's id. The
        // REAL block is a level below, in `executor::apply_batch`'s fresh dependency-proof re-scan
        // (BC-P2-33/BC-P2-11's active-references safety check, which is correct to exist and correct to
        // refuse a non-reference-gated deletion when it finds one): that fresh scan found ONE active
        // reference -- `governance/registry/project-adoption-floor.json` -> `src/app/old_export.py`, kind
        // "path_reference", resolution "glob" -- because the floor file's own `src/**` classification glob is
        // exactly the shape `references.rs`'s pattern-mention scanner treats as a live dependency, and
        // `migrations/ownership.rs::OS_LAYOUT_PREFIXES` (a list independent of, and older than, `paths::
        // OS_STORES`/`t2::OS_MANAGED_PREFIXES`) did not yet know `governance/registry/` is OS-owned, so the
        // scanner did not exclude the floor file the way it already excludes `governance/kernel/`,
        // `governance/project/`, `governance/generated/`, `governance/tests/`. The plugin registry has lived
        // at the same prefix since BC-P2-31 without ever tripping this, because its content never happened to
        // look like a path-glob; the floor is the first `governance/registry/` writer whose entire content is
        // `src/**`-shaped glob rules, and so the first to expose the gap. Fixed at the root cause, in
        // `ownership.rs` (see its own comment) -- not here, and not by touching T2.
        //
        // P2-AR-0096: `reonboarding`/`floor_to_write`/`adoption_floor_reonboarding` were computed ABOVE,
        // before `write_overlay`, so the union could be spliced into the contract too (see that comment) --
        // only the WRITE itself waits for this point, after the install is committed and verified.
        if !already_installed || reonboarding {
            crate::paths::write_project_adoption_floor(root, &floor_to_write, "adopt", None)?;
        }
        entry["installed"] = json!({"version": manifest["version"], "overlay_written": written, "sensitivity_written": sensitivity_written, "destructive_gates_created": gates_created, "release_authenticity": adopt_auth.as_ref().map(|a| a.to_value()), "protected_state": protected, "adoption_floor_reonboarding": adoption_floor_reonboarding});
    } else {
        if n >= 6 && unknown > 0 {
            return Err(GovError::new(
                "UNKNOWN_BLOCKS_DESTRUCTIVE",
                format!(
                    "{unknown} UNKNOWN artefact(s) block destructive batch {n} (protocol §8)"
